def cite(key):
    return f'<a href="{next(url for ident, _, url, _ in SOURCES if ident == key)}">[{key}]</a>'


def percent(number):
    return f"{100 * number:.2f}%"


def table(headers, rows):
    return ('<div class="scroll"><table><thead><tr>' + ''.join(f'<th scope="col">{esc(h)}</th>' for h in headers)
            + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{esc(str(c))}</td>' for c in row) + '</tr>' for row in rows)
            + '</tbody></table></div>')


def bars(filename, title, rows):
    # These are descriptive diagnostics, all sharing a 0-100 percent scale.
    height = 95 + 64 * len(rows)
    parts = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1040 {height}" role="img">',
             f'<title>{esc(title)}</title><rect width="100%" height="100%" fill="white"/>',
             '<g font-family="Arial,sans-serif" fill="#183047" font-size="15">',
             f'<text x="20" y="30" font-size="21" font-weight="bold">{esc(title)}</text>']
    for i, (label, value, color) in enumerate(rows):
        y = 60 + i * 64
        parts += [f'<text x="20" y="{y}">{esc(label)}</text>',
                  f'<rect x="20" y="{y+10}" width="880" height="20" rx="3" fill="#edf2f7"/>',
                  f'<rect x="20" y="{y+10}" width="{880*value:.3f}" height="20" rx="3" fill="{color}"/>',
                  f'<text x="920" y="{y+25}">{percent(value)}</text>']
    parts += [f'<text x="20" y="{height-10}">Same predictions; different matching questions. Higher diagnostic scores are not model improvements.</text>', '</g></svg>']
    svg = ''.join(parts)
    (ROOT / filename).write_text(svg, encoding="utf-8")
    return svg


